/* v60: Phiếu khách gửi trên điện thoại */
.pk-dt { display:grid; gap:10px; }
.pk-tong { display:grid; grid-template-columns:repeat(3, minmax(0,1fr)); gap:8px; }
.pk-tong > div { border-radius:14px; padding:10px 8px; text-align:center; background:var(--xanh2); color:var(--xanh-dam); }
.pk-tong > div.xanh { background:var(--la2); color:var(--la); } .pk-tong > div.do { background:var(--do2); color:var(--do); }
.pk-tong b { display:block; font-size:24px; line-height:1.1; } .pk-tong span { display:block; font-size:12.5px; font-weight:700; margin-top:2px; }
.pk-the { border:1px solid var(--vien); border-radius:14px; padding:10px 12px; display:grid; gap:6px; background:#fff; }
.pk-the.cho { border-left:4px solid var(--do); }
.pk-dau { display:flex; align-items:center; gap:8px; min-width:0; }
.pk-dau > b { flex:1; min-width:0; font-size:15px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pk-ic { flex:none; width:32px; height:32px; border-radius:10px; display:grid; place-items:center; background:var(--xanh2); color:var(--xanh); } .pk-ic .ic svg { width:18px; height:18px; }
.pk-the.cho .pk-ic { background:var(--do2); color:var(--do); }
.pk-nhan { flex:none; font-size:12px; font-weight:800; padding:3px 9px; border-radius:999px; white-space:nowrap; } .pk-nhan.xanh { background:var(--la2); color:var(--la); } .pk-nhan.do { background:var(--do2); color:var(--do); }
.pk-thanh { height:8px; border-radius:5px; background:#eef2f7; overflow:hidden; } .pk-thanh i { display:block; height:100%; border-radius:5px; background:linear-gradient(90deg,#66bb6a,#2e7d32); }
.pk-so { font-size:13px; color:var(--xam); } .pk-so b { color:var(--chu); }
.pk-phu { font-size:12.5px; color:var(--xam); display:flex; align-items:flex-start; gap:5px; } .pk-phu .ic { flex:none; margin-top:1px; } .pk-phu .ic svg { width:14px; height:14px; }
.pk-khong { font-size:12.5px; color:var(--xam); background:#f5f7fa; border-radius:10px; padding:8px 10px; }
  { // v60: điện thoại – phiếu khách gửi thành thẻ từng loại; máy tính giữ bảng
    const tenP = t => t === 'Liên hệ / đổi thông tin' ? 'Liên hệ làm việc' : t;
    const bang = `<div class="cuon"><table class="tk-bang"><tr><th>Loại phiếu</th><th class="so">Phiếu mới</th><th class="so">Đã xử lý</th><th class="so">Đang chờ (tất cả)</th><th class="so">Phản hồi TB</th><th class="so">Trong 24 giờ</th></tr>`
    + r.phieu.map(p => `<tr><td>${esc(tenP(p.ten))}</td><td class="so">${so(p.tong)}</td><td class="so">${so(p.xong)}</td><td class="so">${p.cho ? '<b class="chu-do">' + so(p.cho) + '</b>' : '0'}</td><td class="so">${p.gioTB == null ? '–' : (p.gioTB < 1 ? Math.round(p.gioTB * 60) + ' phút' : String(p.gioTB).replace('.', ',') + ' giờ')}</td><td class="so">${p.coGio ? pt(p.trong24, p.coGio) + '%' : '–'}</td></tr>`).join('') + '</table></div>';
    const ICP = [[/hỏng/i, 'wrench'], [/chất lượng|kiểm tra/i, 'flask'], [/liên hệ/i, 'handshake'], [/vi phạm/i, 'alert'], [/hẹn/i, 'calendar'], [/nộp tiền/i, 'banknote']];
    const icP = t => (ICP.find(x => x[0].test(t)) || [0, 'inbox'])[1];
    const gioP = g => g == null ? '' : (g < 1 ? Math.round(g * 60) + ' phút' : String(g).replace('.', ',') + ' giờ');
    const tongP = r.phieu.reduce((a, p) => a + (p.tong || 0), 0), xongP = r.phieu.reduce((a, p) => a + (p.xong || 0), 0), choP = r.phieu.reduce((a, p) => a + (p.cho || 0), 0);
    const coP = r.phieu.filter(p => p.tong || p.cho).sort((a, b) => (b.cho || 0) - (a.cho || 0) || (b.tong || 0) - (a.tong || 0)), khongP = r.phieu.filter(p => !p.tong && !p.cho);
    const the = `<div class="pk-dt"><div class="pk-tong"><div><b>${so(tongP)}</b><span>Phiếu mới</span></div><div class="xanh"><b>${so(xongP)}</b><span>Đã xử lý</span></div><div class="${choP ? 'do' : 'xanh'}"><b>${so(choP)}</b><span>Đang chờ</span></div></div>`
      + coP.map(p => { const t = tenP(p.ten), ptX = p.tong ? Math.round(p.xong / p.tong * 100) : 0;
        return `<div class="pk-the${p.cho ? ' cho' : ''}"><div class="pk-dau"><span class="pk-ic">${ic(icP(t))}</span><b>${esc(t)}</b><span class="pk-nhan ${p.cho ? 'do' : 'xanh'}">${p.cho ? 'Còn ' + so(p.cho) + ' phiếu chờ' : 'Đã xử lý hết'}</span></div>`
          + (p.tong ? `<div class="pk-thanh"><i style="width:${ptX}%"></i></div><div class="pk-so"><b>${so(p.xong)}/${so(p.tong)}</b> phiếu mới đã xử lý</div>` : `<div class="pk-so">Không có phiếu mới – còn phiếu cũ đang chờ</div>`)
          + (p.gioTB != null || p.coGio ? `<div class="pk-phu">${ic('clock')}<span>${p.gioTB != null ? 'Phản hồi trung bình ' + gioP(p.gioTB) : ''}${p.gioTB != null && p.coGio ? ' · ' : ''}${p.coGio ? pt(p.trong24, p.coGio) + '% xử lý trong 24 giờ' : ''}</span></div>` : '') + '</div>'; }).join('')
      + (khongP.length ? `<div class="pk-khong">Không có phiếu trong ${r.soNgay} ngày: ${khongP.map(p => esc(tenP(p.ten))).join(', ')}</div>` : '')
      + (!coP.length ? '<div class="pk-khong">Chưa có phiếu nào.</div>' : '') + '</div>';
    h += `<div class="the"><h3>${ic('inbox')} Phiếu khách gửi – ${r.soNgay} ngày</h3>${hep600() ? the : bang}</div>`;
  }
